const insertNonce = `-- name: InsertNonce :exec
INSERT INTO pc.dpop_nonces (org_id, minute, nonce) VALUES ($1, $2, $3)
ON CONFLICT (org_id, minute) DO NOTHING
`

// Nonces (HR-091): one per org per minute, accepted until 6 minutes after
// the start of their minute.
func (q *Queries) InsertNonce(ctx context.Context, orgID ids.OrgID, minute int64, nonce string) error {
	_, err := q.db.Exec(ctx, insertNonce, orgID, minute, nonce)
	return err
}

const insertProofJTI = `-- name: InsertProofJTI :execrows
INSERT INTO pc.dpop_jti (org_id, slot, jkt, jti, nonce_minute)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT DO NOTHING
`

type InsertProofJTIParams struct {
	OrgID       ids.OrgID
	Slot        int16
	Jkt         string
	Jti         string
	NonceMinute int64
}

// Records a proof's (jkt, jti) in its nonce's slot; no row means a replay
// (HR-090). Only called after the proof verified and its nonce is live.
func (q *Queries) InsertProofJTI(ctx context.Context, arg InsertProofJTIParams) (int64, error) {
	result, err := q.db.Exec(ctx, insertProofJTI,
		arg.OrgID,
		arg.Slot,
		arg.Jkt,
		arg.Jti,
		arg.NonceMinute,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

