const listInstances = `-- name: ListInstances :many
SELECT org_id, id, agent_id, jkt, public_jwk, state, enrolled_via, enrollment_token_id, issuer_revision_id, binding, att_level, attested_until, release_state, release_digest, needs_review, last_network, last_seen_at, decided_by, decided_at, revoke_reason, created_at, updated_at, expires_at, sandbox_session_id FROM pc.agent_instances
WHERE org_id = $1 AND agent_id = $2
  AND id > coalesce($3::uuid, '00000000-0000-0000-0000-000000000000')
  AND (cardinality($4::text[]) = 0 OR state = ANY ($4::text[]))
ORDER BY id
LIMIT $5
`

type ListInstancesParams struct {
	OrgID     ids.OrgID
	AgentID   ids.UUID
	After     ids.UUID
	States    []string
	PageLimit int32
}

func (q *Queries) ListInstances(ctx context.Context, arg ListInstancesParams) ([]PcAgentInstance, error) {
	rows, err := q.db.Query(ctx, listInstances,
		arg.OrgID,
		arg.AgentID,
		arg.After,
		arg.States,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PcAgentInstance{}
	for rows.Next() {
		var i PcAgentInstance
		if err := rows.Scan(
			&i.OrgID,
			&i.ID,
			&i.AgentID,
			&i.Jkt,
			&i.PublicJwk,
			&i.State,
			&i.EnrolledVia,
			&i.EnrollmentTokenID,
			&i.IssuerRevisionID,
			&i.Binding,
			&i.AttLevel,
			&i.AttestedUntil,
			&i.ReleaseState,
			&i.ReleaseDigest,
			&i.NeedsReview,
			&i.LastNetwork,
			&i.LastSeenAt,
			&i.DecidedBy,
			&i.DecidedAt,
			&i.RevokeReason,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ExpiresAt,
			&i.SandboxSessionID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

